contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(amount == 10);
        require(address(this).balance >= amount);
        uint oldPot = c.pot(); if (__ESBMC_reverted()) return;
        c.play{value: amount}(); if (__ESBMC_reverted()) return;
        uint newPot = c.pot(); if (__ESBMC_reverted()) return;
        assert(newPot == 0 || newPot == oldPot + 10);
        // The rejected rule also implied balance non-decrease unless pot reset; add that here.
        // Since we cannot know the random draw, just assert the pot invariant.
        // Balance invariant: if pot did not reset, balance must have increased.
        // We can only assert it in the branch where pot != 0.
        if (newPot != 0) {
            assert(address(c).balance >= amount);
        }
    }
}

